function evalRecursive(expr) {
  if (typeof expr === 'number') return expr;
  const [op, leftExpr, rightExpr] = expr;
  const left = evalRecursive(leftExpr);
  const right = evalRecursive(rightExpr);
  if (op === '+') return left + right;
  if (op === '*') return left * right;
  throw new Error('unsupported');
}

console.log(evalRecursive(['+', 2, ['*', 3, 4]]));

